// Traduz a resposta da fonte para o formato que o importador do site le.
// Um objeto por celula da planilha: chave + fonte + campo + valor.
const saida = [];

for (const item of $input.all()) {
  const candidato = $('Um de cada vez').first().json;
  const corpo = typeof item.json.data === 'string' ? item.json.data : (item.json.body || '');

  const titulos = [...corpo.matchAll(/<title><!\[CDATA\[(.*?)\]\]><\/title>/g)].map(m => m[1]);
  // O primeiro <title> do RSS e o titulo do proprio feed, nao uma materia.
  const materias = titulos.slice(1);

  const busca = 'https://news.google.com/search?q=' +
    encodeURIComponent('"' + candidato.nm_candidato + '" ' + candidato.sg_uf) +
    '&hl=pt-BR&gl=BR&ceid=BR%3Apt-419';

  saida.push({
    json: {
      chave: candidato.chave,
      fonte: $('Recorte a coletar').first().json.fonte,
      campo: $('Recorte a coletar').first().json.campo,
      valor: materias.length + ' materia(s)',
      valor_num: materias.length,
      url: busca,
      observacao: 'Coletado pelo fluxo do n8n a partir do feed publico de busca. A contagem mede repercussao, nao veracidade.',
      coletado_em: new Date().toISOString(),
    },
  });
}

return saida;
